// Format a Slack/Discord/Gmail-friendly summary of which users were auto-closed.
const closed = ($json.closed || []);
const lines = closed.map(c => {
  const h = Math.floor(c.durationSeconds / 3600);
  const m = Math.floor((c.durationSeconds % 3600) / 60);
  return `• user_id=${c.userId} → ${h}h ${m}m`;
});
return [{
  json: {
    ranAt: $json.ranAt,
    closedCount: closed.length,
    summary: `Auto-closed ${closed.length} stale session(s) at ${$json.ranAt}\n${lines.join('\n')}`,
  }
}];
